import React, { useState, useEffect } from 'react';
import Modal from '../common/Modal';

const priorities = ['Low', 'Medium', 'High', 'Urgent'];

const TaskFormModal = ({ isOpen, onClose, onSubmit, projects = [], employees = [], initialData = null, isEdit = false }) => {
  const [formData, setFormData] = useState({
    taskTitle: '',
    project: '',
    assignedTo: [],
    priority: 'Medium',
    estimatedHours: 10,
    deadline: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    taskPaymentAmount: 250,
    description: '',
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        taskTitle: initialData.taskTitle || '',
        project: initialData.project ? (typeof initialData.project === 'object' ? initialData.project._id : initialData.project) : '',
        assignedTo: initialData.assignedTo
          ? initialData.assignedTo.map((e) => (typeof e === 'object' ? e._id : e))
          : [],
        priority: initialData.priority || 'Medium',
        estimatedHours: initialData.estimatedHours || 10,
        deadline: initialData.deadline ? new Date(initialData.deadline).toISOString().split('T')[0] : '',
        taskPaymentAmount: initialData.taskPaymentAmount || 0,
        description: initialData.description || '',
      });
    } else {
      setFormData({
        taskTitle: '',
        project: projects[0]?._id || '',
        assignedTo: [],
        priority: 'Medium',
        estimatedHours: 10,
        deadline: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        taskPaymentAmount: 250,
        description: '',
      });
    }
  }, [initialData, isOpen, projects]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleEmployeeToggle = (empId) => {
    setFormData((prev) => {
      const exists = prev.assignedTo.includes(empId);
      if (exists) {
        return { ...prev, assignedTo: prev.assignedTo.filter((id) => id !== empId) };
      } else {
        return { ...prev, assignedTo: [...prev.assignedTo, empId] };
      }
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(formData);
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title={isEdit ? `Edit Task - ${initialData?.taskId}` : 'Create & Assign Task'}
      maxWidth="700px"
    >
      <form onSubmit={handleSubmit}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
          <div className="form-group" style={{ gridColumn: 'span 2' }}>
            <label className="form-label">Task Title *</label>
            <input
              type="text"
              name="taskTitle"
              className="form-input"
              value={formData.taskTitle}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label">Publication Project *</label>
            <select name="project" className="form-select" value={formData.project} onChange={handleChange} required>
              <option value="">Select Project</option>
              {projects.map((p) => (
                <option key={p._id} value={p._id}>
                  {p.bookName} ({p.projectId})
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label className="form-label">Priority</label>
            <select name="priority" className="form-select" value={formData.priority} onChange={handleChange}>
              {priorities.map((p) => (
                <option key={p} value={p}>
                  {p}
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label className="form-label">Task Payment Amount ($) *</label>
            <input
              type="number"
              name="taskPaymentAmount"
              className="form-input"
              value={formData.taskPaymentAmount}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label className="form-label">Estimated Hours</label>
            <input
              type="number"
              name="estimatedHours"
              className="form-input"
              value={formData.estimatedHours}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label className="form-label">Deadline Date *</label>
            <input
              type="date"
              name="deadline"
              className="form-input"
              value={formData.deadline}
              onChange={handleChange}
              required
            />
          </div>
        </div>

        <div className="form-group" style={{ marginTop: '12px' }}>
          <label className="form-label">Assign Employees (Multiple Selection)</label>
          <div
            style={{
              maxHeight: '120px',
              overflowY: 'auto',
              border: '1px solid var(--border-color)',
              borderRadius: '10px',
              padding: '10px',
              background: 'var(--bg-input)',
              display: 'grid',
              gridTemplateColumns: '1fr 1fr',
              gap: '8px',
            }}
          >
            {employees.map((emp) => (
              <label
                key={emp._id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                  fontSize: '0.85rem',
                  cursor: 'pointer',
                }}
              >
                <input
                  type="checkbox"
                  checked={formData.assignedTo.includes(emp._id)}
                  onChange={() => handleEmployeeToggle(emp._id)}
                />
                {emp.fullName} ({emp.department})
              </label>
            ))}
          </div>
        </div>

        <div className="form-group">
          <label className="form-label">Task Instructions & Requirements</label>
          <textarea
            name="description"
            className="form-textarea"
            rows="3"
            value={formData.description}
            onChange={handleChange}
          />
        </div>

        <div className="modal-footer" style={{ padding: '16px 0 0 0' }}>
          <button type="button" className="btn btn-secondary" onClick={onClose}>
            Cancel
          </button>
          <button type="submit" className="btn btn-primary">
            {isEdit ? 'Save Task' : 'Assign Task'}
          </button>
        </div>
      </form>
    </Modal>
  );
};

export default TaskFormModal;
